672	// ---- 持久化 ----
673	
674	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
675	func (s *Store) loadLocked() (*storedState, error) {
676		raw, err := os.ReadFile(s.path)
677		if err != nil {
678			return nil, err
679		}
680		if len(bytes.TrimSpace(raw)) == 0 {
681			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
682		}
683		if err := checkStateStructure(raw); err != nil {
684			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
685		}
686		var state storedState
687		dec := json.NewDecoder(bytes.NewReader(raw))
688		dec.DisallowUnknownFields()
689		if err := dec.Decode(&state); err != nil {
690			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
691		}
692		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
693		var extra json.RawMessage
694		if err := dec.Decode(&extra); err != io.EOF {
695			if err == nil {
696				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
697			}
698			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
699		}
700		if err := validateState(&state); err != nil {
701			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
702		}
703		return &state, nil
704	}
705	
706	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
707	// 任一步失败都保留上次完整状态。调用方必须持锁。
708	func (s *Store) commitLocked(state *storedState) error {
709		if err := validateState(state); err != nil {
710			return fmt.Errorf("refusing to persist invalid state: %w", err)
711		}
712		payload, err := json.MarshalIndent(state, "", "  ")
713		if err != nil {
714			return err
715		}
716		payload = append(payload, '\n')
717	
718		dir := filepath.Dir(s.path)
719		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
720		if err != nil {
721			return err
722		}
723		tmpName := tmp.Name()
724		cleanup := func() { _ = os.Remove(tmpName) }
725		if _, err := tmp.Write(payload); err != nil {
726			_ = tmp.Close()
727			cleanup()
728			return err
729		}
730		if err := tmp.Sync(); err != nil {
731			_ = tmp.Close()
732			cleanup()
733			return err
734		}
735		if err := tmp.Close(); err != nil {
736			cleanup()
737			return err
738		}
739		if err := os.Chmod(tmpName, 0o600); err != nil {
740			cleanup()
741			return err
742		}
743		if err := os.Rename(tmpName, s.path); err != nil {
744			cleanup()
745			return err
746		}
747		if err := syncDir(dir); err != nil {
748			return err
749		}
750		return nil
751	}
752	
753	func syncDir(dir string) error {
754		d, err := os.Open(dir)
755		if err != nil {
756			return err
757		}
758		defer d.Close()
759		return d.Sync()
760	}
