762	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
763	func validateState(state *storedState) error {
764		if state.Magic != stateMagic {
765			return fmt.Errorf("bad magic %q", state.Magic)
766		}
767		if state.Version != stateVersion {
768			return fmt.Errorf("unsupported state version %d", state.Version)
769		}
770		if state.InitialTreasury < 0 {
771			return errors.New("initial treasury balance is negative")
772		}
773		if state.Treasury < 0 {
774			return errors.New("treasury balance is negative")
775		}
776		if state.Balances == nil {
777			return errors.New("balances table is missing")
778		}
779		if state.Proposals == nil {
780			return errors.New("proposals table is missing")
781		}
782		if state.Receipts == nil {
783			return errors.New("receipts table is missing")
784		}
785		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
786		if state.VoteProposals == nil {
787			state.VoteProposals = map[string]*storedVoteProposal{}
788		}
789		for account, balance := range state.Balances {
790			if account == "" {
791				return errors.New("balance entry with empty account")
792			}
793			if balance < 0 {
794				return fmt.Errorf("balance of %q is negative", account)
795			}
796		}
797		for key, p := range state.Proposals {
798			if p == nil {
799				return fmt.Errorf("proposal %q is empty", key)
800			}
801			if p.ID != key || p.ID == "" {
802				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
803			}
804			if p.State != "passed" && p.State != "executed" {
805				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
806			}
807			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
808		}
809		if err := validateVoteProposals(state); err != nil {
810			return err
811		}
812	
813		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
814		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
815		simTreasury := state.InitialTreasury
816		simBalances := map[string]int64{}
817		seenReceipts := map[string]int{}
818		for order, rcpt := range state.Receipts {
819			if rcpt == nil {
820				return fmt.Errorf("receipt %d is empty", order)
821			}
822			if rcpt.Order != order {
823				return fmt.Errorf("receipt %q order field is %d, expected %d", rcpt.ProposalID, rcpt.Order, order)
824			}
825			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
826				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
827			}
828			seenReceipts[rcpt.ProposalID] = order
829			ownerState, ownerTimelock, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
830			if !found {
831				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
832			}
833			if ownerState != "executed" {
834				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
835			}
836			// 保存的凭据与首次执行受同一条执行资格规则约束：executed_at 必须明确
837			// 写出且不得早于提案时间锁。登记提案与投票提案共用这一判断。
838			if err := validateReceiptExecutedAt(order, rcpt, ownerTimelock); err != nil {
839				return err
840			}
841			// 凭据声明的逐笔转账由统一转账规则（verifyReceiptTransfers）重放
842			// 核对：动作条数/编号/原文、资金库与收款账户前后余额任一不符都带
843			// 动作位置报损坏原因；本函数随即返回错误，整份状态被拒绝，重放结果
844			// 不会被查询或落盘采纳。
845			var verr error
846			simTreasury, verr = verifyReceiptTransfers(rcpt, ownerActions, simTreasury, simBalances)
847			if verr != nil {
848				return verr
849			}
850		}
851		if simTreasury != state.Treasury {
852			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
853		}
854		if len(simBalances) != len(state.Balances) {
855			return fmt.Errorf("balance table has %d accounts, receipt replay yields %d", len(state.Balances), len(simBalances))
856		}
857		for account, balance := range state.Balances {
858			if simBalances[account] != balance {
859				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
860			}
861		}
862		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
863		for _, p := range state.Proposals {
864			_, hasReceipt := seenReceipts[p.ID]
865			if p.State == "executed" && !hasReceipt {
866				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
867			}
868		}
869		for _, p := range state.VoteProposals {
870			_, hasReceipt := seenReceipts[p.ID]
871			if p.State == "executed" && !hasReceipt {
872				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
873			}
874		}
875		return nil
876	}
877	
878	// validateReceiptExecutedAt 严格判定一份已保存凭据的 executed_at：
879	// 字段未写出、显式为 null 或不是 int64 整数都返回带定位的错误；
880	// 明确写出的值必须不早于所属提案的 timelock_end（恰好等于时间锁有效，
881	// 时间锁允许 0 时明确写出的 0 同样有效）。order 是凭据在凭据表中的
882	// 位置（0 起），与提案编号一起用于定位。
883	func validateReceiptExecutedAt(order int, rcpt *Receipt, timelockEnd int64) error {
884		raw := rcpt.executedAtRaw
885		switch {
886		case raw == nil:
887			return fmt.Errorf("receipt %d for proposal %q field %q is missing", order, rcpt.ProposalID, "executed_at")
888		case string(raw) == "null":
889			return fmt.Errorf("receipt %d for proposal %q field %q is null", order, rcpt.ProposalID, "executed_at")
890		case !isInt64Number(raw):
891			return fmt.Errorf("receipt %d for proposal %q field %q has wrong type: want integer, got %s",
892				order, rcpt.ProposalID, "executed_at", jsonValueType(raw))
893		}
894		if rcpt.ExecutedAt < timelockEnd {
895			return fmt.Errorf("receipt %d for proposal %q executed_at %d is before timelock_end %d",
896				order, rcpt.ProposalID, rcpt.ExecutedAt, timelockEnd)
897		}
898		return nil
899	}
