901	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
902	
903	// schemaKind 是状态文件 JSON 在某一层的形状类别。
904	type schemaKind int
905	
906	const (
907		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
908		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
909		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
910		kindArray                     // 数组
911		kindString                    // 叶子：必须是 JSON 字符串
912		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
913		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
914	)
915	
916	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
917	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
918	type schemaNode struct {
919		kind   schemaKind
920		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
921		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
922	}
923	
924	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
925	func schemaOf(t reflect.Type) *schemaNode {
926		for t.Kind() == reflect.Pointer {
927			t = t.Elem()
928		}
929		switch t.Kind() {
930		case reflect.Struct:
931			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
932			for i := 0; i < t.NumField(); i++ {
933				f := t.Field(i)
934				if f.PkgPath != "" { // 未导出字段不参与 JSON
935					continue
936				}
937				name := f.Name
938				if tag, ok := f.Tag.Lookup("json"); ok {
939					tagName, _, _ := strings.Cut(tag, ",")
940					if tagName == "-" {
941						continue
942					}
943					if tagName != "" {
944						name = tagName
945					}
946				}
947				node.fields[name] = schemaOf(f.Type)
948			}
949			return node
950		case reflect.Map:
951			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
952		case reflect.Slice, reflect.Array:
953			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
954		case reflect.String:
955			return &schemaNode{kind: kindString}
956		case reflect.Bool:
957			return &schemaNode{kind: kindBoolean}
958		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
959			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
960			return &schemaNode{kind: kindInteger}
961		default:
962			return &schemaNode{kind: kindAny}
963		}
964	}
965	
966	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
967	
968	func init() {
969		// 票据的四个标量字段（representative/weight/support/voted_at）由
970		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
971		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
972		// 不抢在解码器之前用不含票据定位的通用信息报错。
973		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
974		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
975			ballotFields[name].kind = kindAny
976		}
977		// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
978		// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
979		// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
980		// 其“不早于截止”的既有校验不变。
981		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
982		for _, name := range []string{"for_weight", "against_weight"} {
983			tallyFields[name].kind = kindAny
984		}
985		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
986		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
987		// 叶子位置保持宽松。
988		storedStateSchema.fields["receipts"].elem.fields["executed_at"].kind = kindAny
989	}
