991	// scanFrame 是结构扫描的栈帧。
992	type scanFrame struct {
993		node    *schemaNode
994		isArray bool
995		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
996		seen    map[string]bool
997		atValue bool // 对象帧：下一个待消费 token 是值而非键
998		index   int  // 数组帧：下一个元素下标
999		path    string
1000	}
1001	
1002	func peekFrame(stack []*scanFrame) *scanFrame {
1003		if len(stack) == 0 {
1004			return nil
1005		}
1006		return stack[len(stack)-1]
1007	}
1008	
1009	// checkStateStructure 在解码前逐 token 扫描状态文件：
1010	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1011	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1012	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1013	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1014	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1015	//
1016	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1017	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1018	func checkStateStructure(raw []byte) error {
1019		dec := json.NewDecoder(bytes.NewReader(raw))
1020		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1021		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1022		dec.UseNumber()
1023		var stack []*scanFrame
1024		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1025		pendingNode := storedStateSchema
1026		pendingPath := "state"
1027	
1028		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1029		finishValue := func() {
1030			top := peekFrame(stack)
1031			if top == nil || top.opaque {
1032				return
1033			}
1034			if top.isArray {
1035				top.index++
1036			} else {
1037				top.atValue = false
1038			}
1039		}
1040	
1041		for {
1042			tok, err := dec.Token()
1043			if err == io.EOF {
1044				if len(stack) != 0 {
1045					return errors.New("unterminated object or array")
1046				}
1047				return nil
1048			}
1049			if err != nil {
1050				return err
1051			}
1052	
1053			if top := peekFrame(stack); top != nil && top.opaque {
1054				// 不透明容器内不做字段检查，只配对括号。
1055				if d, ok := tok.(json.Delim); ok {
1056					if d == '{' || d == '[' {
1057						stack = append(stack, &scanFrame{opaque: true})
1058					} else {
1059						stack = stack[:len(stack)-1]
1060						finishValue()
1061					}
1062				}
1063				continue
1064			}
1065	
1066			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1067				// 对象帧的键位置：闭括号或下一个键。
1068				if d, ok := tok.(json.Delim); ok {
1069					if d != '}' {
1070						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1071					}
1072					stack = stack[:len(stack)-1]
1073					finishValue()
1074					continue
1075				}
1076				key, ok := tok.(string)
1077				if !ok {
1078					return errors.New("object key must be a string")
1079				}
1080				if top.seen[key] {
1081					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1082				}
1083				top.seen[key] = true
1084				top.atValue = true
1085				switch top.node.kind {
1086				case kindObject:
1087					child, known := top.node.fields[key]
1088					if !known {
1089						return fmt.Errorf("unknown field %q at %s", key, top.path)
1090					}
1091					pendingNode = child
1092					pendingPath = top.path + "." + key
1093				case kindMap:
1094					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1095					pendingNode = top.node.elem
1096					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1097				}
1098				continue
1099			}
1100	
1101			// 值位置：对象键之后的值或数组元素。
1102			node := pendingNode
1103			path := pendingPath
1104			if top := peekFrame(stack); top != nil && top.isArray {
1105				node = top.node.elem
1106				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1107			}
1108			if d, ok := tok.(json.Delim); ok {
1109				switch d {
1110				case '{', '[':
1111					frame := &scanFrame{isArray: d == '[', path: path}
1112					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1113						(d == '[' && node.kind == kindArray)
1114					if !shapeOK {
1115						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1116						frame.opaque = true
1117					} else {
1118						frame.node = node
1119						if d == '{' {
1120							frame.seen = map[string]bool{}
1121						}
1122					}
1123					stack = append(stack, frame)
1124				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1125					if len(stack) == 0 {
1126						return errors.New("unexpected closing delimiter")
1127					}
1128					stack = stack[:len(stack)-1]
1129					finishValue()
1130				}
1131				continue
1132			}
1133			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1134			// null 不允许用来顶替字符串/布尔/整数。
1135			if err := checkLeafScalar(node, path, tok); err != nil {
1136				return err
1137			}
1138			finishValue()
1139		}
1140	}
1141	
1142	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1143	func leafKindName(k schemaKind) string {
1144		switch k {
1145		case kindString:
1146			return "string"
1147		case kindBoolean:
1148			return "boolean"
1149		case kindInteger:
1150			return "integer"
1151		default:
1152			return "value"
1153		}
1154	}
1155	
1156	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1157	func tokenKindName(tok json.Token) string {
1158		switch v := tok.(type) {
1159		case nil:
1160			return "null"
1161		case string:
1162			return "string"
1163		case bool:
1164			return "boolean"
1165		case json.Number:
1166			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1167				return "integer"
1168			}
1169			return "number"
1170		default:
1171			return "value"
1172		}
1173	}
1174	
1175	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1176	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1177	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1178		switch node.kind {
1179		case kindString, kindBoolean, kindInteger:
1180		default:
1181			return nil
1182		}
1183		if node.kind == kindInteger {
1184			if n, ok := tok.(json.Number); ok {
1185				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1186					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1187				}
1188				return nil
1189			}
1190		}
1191		want := leafKindName(node.kind)
1192		if got := tokenKindName(tok); got != want {
1193			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1194		}
1195		return nil
1196	}
1197

