32	// Delegation 表示 From 把投票权委托给 To。委托可以继续转交，
33	// 最终未再委托的人代表沿途所有成员投票。
34	type Delegation struct {
35		From string `json:"from"`
36		To   string `json:"to"`
37	}
38	
39	// CreateVoteInput 是创建一项投票提案的完整输入。
40	type CreateVoteInput struct {
41		ID          string
42		Members     []VoteMember
43		Delegations []Delegation
44		Quorum      int64
45		StartAt     int64
