94	// ---- 磁盘结构（JSON，版本仍为 1） ----
95	
96	type storedMember struct {
97		ID     string `json:"id"`
98		Weight int64  `json:"weight"`
99	}
100	
101	type storedDelegation struct {
102		From string `json:"from"`
103		To   string `json:"to"`
104	}
105	
106	// storedBallot 是一张已保存的票。四个字段都必须明确写出、非空且类型正确：
107	// representative 是 JSON 字符串，weight/voted_at 是 JSON 整数（int64 范围），
108	// support 必须是 JSON 布尔值。绝不能靠零值/默认值补出治理记录：
109	// 缺失或 null 的 support 不得被当作 false（反对票），缺失或 null 的
110	// voted_at 不得被当作 0（首次投票时间）。
111	//
112	// 标量字段先用 RawMessage 接住，使“字段缺失”与“显式 null/写错类型”在解码后
113	// 仍可区分：encoding/json 直接解进 bool/int64/string 时会把这三种情况都
114	// 折叠成零值。每个字段的“缺失/空值/类型不符”由 validateStoredBallot 判定。
115	type storedBallot struct {
116		Representative string `json:"representative"`
117		Weight         int64  `json:"weight"`
118		Support        bool   `json:"support"`
119		VotedAt        int64  `json:"voted_at"`
120	
121		representativeRaw json.RawMessage
122		weightRaw         json.RawMessage
123		supportRaw        json.RawMessage
124		votedAtRaw        json.RawMessage
125	}
126	
127	// ballotJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
128	type ballotJSONShape struct {
129		Representative json.RawMessage `json:"representative"`
130		Weight         json.RawMessage `json:"weight"`
131		Support        json.RawMessage `json:"support"`
132		VotedAt        json.RawMessage `json:"voted_at"`
133	}
134	
135	// UnmarshalJSON 保留字段是否出现及其原始写法（缺失为 nil、null 为 "null"），
136	// 供 validateStoredBallot 区分缺失、空值与类型不符。单个字段类型不符时这里
137	// 不返回错误（对应治理字段保持零值），以免解码器在不含提案编号/票据下标的
138	// 通用错误处提前失败；定位与判定统一交给 validateStoredBallot。
139	func (b *storedBallot) UnmarshalJSON(data []byte) error {
140		var shape ballotJSONShape
141		if err := json.Unmarshal(data, &shape); err != nil {
142			return err
143		}
144		b.representativeRaw, b.weightRaw = shape.Representative, shape.Weight
145		b.supportRaw, b.votedAtRaw = shape.Support, shape.VotedAt
146		// 仅当字段确实是目标类型时才填充治理字段；类型不符留待校验拒绝，
147		// 绝不能让错误类型悄悄落成零值并参与查询或计票。
148		if raw := shape.Representative; jsonValueType(raw) == "string" {
149			_ = json.Unmarshal(raw, &b.Representative)
150		}
151		if raw := shape.Weight; isInt64Number(raw) {
152			_ = json.Unmarshal(raw, &b.Weight)
153		}
154		if raw := shape.Support; jsonValueType(raw) == "boolean" {
155			_ = json.Unmarshal(raw, &b.Support)
156		}
157		if raw := shape.VotedAt; isInt64Number(raw) {
158			_ = json.Unmarshal(raw, &b.VotedAt)
159		}
160		return nil
161	}
162	
163	// MarshalJSON 只输出四个治理字段，RawMessage 状态（仅用于入站判定）不落盘。
164	func (b storedBallot) MarshalJSON() ([]byte, error) {
165		return json.Marshal(storedBallotOut{
166			Representative: b.Representative,
167			Weight:         b.Weight,
168			Support:        b.Support,
169			VotedAt:        b.VotedAt,
170		})
171	}
172	
173	// storedBallotOut 是票据的保存形状；字段名与保存格式逐字一致。
174	type storedBallotOut struct {
175		Representative string `json:"representative"`
176		Weight         int64  `json:"weight"`
177		Support        bool   `json:"support"`
178		VotedAt        int64  `json:"voted_at"`
179	}
180	
181	// mustStoreBallot 构造一张内存中的合法票据（投票成功路径使用）。
182	// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
183	// validateStoredBallot 判定时不会把本进程新建的票据误判为字段缺失。
184	func mustStoreBallot(representative string, weight int64, support bool, votedAt int64) storedBallot {
185		repRaw, _ := json.Marshal(representative)
186		wRaw, _ := json.Marshal(weight)
187		supRaw, _ := json.Marshal(support)
188		atRaw, _ := json.Marshal(votedAt)
189		return storedBallot{
190			Representative:    representative,
191			Weight:            weight,
192			Support:           support,
193			VotedAt:           votedAt,
194			representativeRaw: repRaw,
195			weightRaw:         wRaw,
196			supportRaw:        supRaw,
197			votedAtRaw:        atRaw,
198		}
199	}
200	
201	// validateStoredBallot 严格判定一张已保存票据的四个必填字段：
202	// 任一字段未写出、显式为 null 或 JSON 类型不符（support 不接受字符串/数字，
203	// weight/voted_at 不接受字符串/小数/指数等非整数）都返回带原因的错误。
204	// 明确写出的 false 是有效反对票；窗口允许时明确写出的 0 是有效投票时间，
205	// 这两种合法值不得当成缺失。index 是票据在提案中的下标（0 起），用于定位。
206	func validateStoredBallot(id string, index int, b *storedBallot) error {
207		check := func(field string, raw json.RawMessage, kind string, decode func() error) error {
208			switch {
209			case raw == nil:
210				return fmt.Errorf("voting proposal %q ballot %d field %q is missing", id, index, field)
211			case string(raw) == "null":
212				return fmt.Errorf("voting proposal %q ballot %d field %q is null", id, index, field)
213			default:
214				if err := decode(); err != nil {
215					return fmt.Errorf("voting proposal %q ballot %d field %q has wrong type: want %s, got %s",
216						id, index, field, kind, jsonValueType(raw))
217				}
218				return nil
219			}
220		}
221		if err := check("representative", b.representativeRaw, "string", func() error {
222			return json.Unmarshal(b.representativeRaw, new(string))
223		}); err != nil {
224			return err
225		}
226		if err := check("weight", b.weightRaw, "integer", func() error {
227			return json.Unmarshal(b.weightRaw, new(int64))
228		}); err != nil {
229			return err
230		}
231		if err := check("support", b.supportRaw, "boolean", func() error {
232			return json.Unmarshal(b.supportRaw, new(bool))
233		}); err != nil {
234			return err
235		}
236		if err := check("voted_at", b.votedAtRaw, "integer", func() error {
237			return json.Unmarshal(b.votedAtRaw, new(int64))
238		}); err != nil {
239			return err
240		}
241		return nil
242	}
243	
244	// jsonValueType 按字段实际写出 JSON 的首字节归类其 JSON 类型。
245	// RawMessage 是从合法 JSON 文档中取出的单个值，首字节足以区分
246	// 字符串/布尔/null/数字/数组/对象，无需再次解码。
247	func jsonValueType(raw json.RawMessage) string {
248		for _, c := range raw {
249			switch c {
250			case ' ', '\t', '\n', '\r':
251				continue
252			case '"':
253				return "string"
254			case 't', 'f':
255				return "boolean"
256			case 'n':
257				return "null"
258			case '[':
259				return "array"
260			case '{':
261				return "object"
262			default:
263				return "number"
264			}
265		}
266		return "invalid json"
267	}
268	
269	// isInt64Number 判断原始 JSON 是否为落在有符号 64 位整数范围内的整数字面量：
270	// 必须是 JSON 数字（首字节为数字或 '-'），且能被 ParseInt 以 10 进制精确解析。
271	// 小数、指数、超界整数均返回 false。
272	func isInt64Number(raw json.RawMessage) bool {
273		if jsonValueType(raw) != "number" {
274			return false
275		}
276		_, err := strconv.ParseInt(strings.TrimSpace(string(raw)), 10, 64)
277		return err == nil
278	}
279	
280	// storedTally 是已保存的首次计票结果。只要提案有计票结果，for_weight 与
281	// against_weight 就必须各自明确写出：即使某一侧（或两侧）的实际票重为零，
282	// 也不得靠零值/默认值补出治理记录——缺失或 null 的 for_weight 不得被当作 0
283	// 赞成，缺失或 null 的 against_weight 不得被当作 0 反对。
284	//
285	// 两个权重字段先用 RawMessage 接住，使“字段缺失”与“显式 null/写错类型”在解码后
286	// 仍可区分：encoding/json 直接解进 int64 时会把这三种情况都折叠成 0，恰好与
287	// “该侧没有票”的合法零权重无法区分。每个字段的“缺失/空值/类型不符”由
288	// validateStoredTally 判定。
289	type storedTally struct {
290		ForWeight     int64 `json:"for_weight"`
291		AgainstWeight int64 `json:"against_weight"`
292		TalliedAt     int64 `json:"tallied_at"`
293	
294		forWeightRaw     json.RawMessage
295		againstWeightRaw json.RawMessage
296	}
297	
298	// tallyJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
299	type tallyJSONShape struct {
300		ForWeight     json.RawMessage `json:"for_weight"`
301		AgainstWeight json.RawMessage `json:"against_weight"`
302		TalliedAt     int64           `json:"tallied_at"`
303	}
304	
305	// UnmarshalJSON 保留两个权重字段是否出现及其原始写法（缺失为 nil、null 为
306	// "null"），供 validateStoredTally 区分缺失、空值与类型不符。单个字段类型不符时
307	// 这里不返回错误（对应治理字段保持零值），以免解码器在不含提案编号的通用错误处
308	// 提前失败；定位与判定统一交给 validateStoredTally。
309	func (t *storedTally) UnmarshalJSON(data []byte) error {
310		var shape tallyJSONShape
311		if err := json.Unmarshal(data, &shape); err != nil {
312			return err
313		}
314		t.forWeightRaw, t.againstWeightRaw = shape.ForWeight, shape.AgainstWeight
315		t.TalliedAt = shape.TalliedAt
316		// 仅当字段确实是 int64 整数时才填充治理字段；类型不符留待校验拒绝，
317		// 绝不能让错误类型悄悄落成 0 并参与查询或再次计票。
318		if isInt64Number(shape.ForWeight) {
319			_ = json.Unmarshal(shape.ForWeight, &t.ForWeight)
320		}
321		if isInt64Number(shape.AgainstWeight) {
322			_ = json.Unmarshal(shape.AgainstWeight, &t.AgainstWeight)
323		}
324		return nil
325	}
326	
327	// mustStoreTally 构造一份内存中的合法计票结果（首次计票路径使用）。
328	// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
329	// validateStoredTally 判定时不会把本进程新建的计票结果误判为字段缺失。
330	func mustStoreTally(forWeight, againstWeight, talliedAt int64) *storedTally {
331		forRaw, _ := json.Marshal(forWeight)
332		againstRaw, _ := json.Marshal(againstWeight)
333		return &storedTally{
334			ForWeight:        forWeight,
335			AgainstWeight:    againstWeight,
336			TalliedAt:        talliedAt,
337			forWeightRaw:     forRaw,
338			againstWeightRaw: againstRaw,
339		}
340	}
341	
342	// validateStoredTally 严格判定一份已保存计票结果的两个权重字段：
343	// for_weight 与 against_weight 任一未写出、显式为 null 或不是 int64 整数
344	// （字符串/小数/指数/超界）都返回带提案编号、字段名与原因的错误。
345	// 明确写出的 0 是合法权重（该侧没有票），不得当成缺失。
346	func validateStoredTally(id string, t *storedTally) error {
347		check := func(field string, raw json.RawMessage) error {
348			switch {
349			case raw == nil:
350				return fmt.Errorf("voting proposal %q tally field %q is missing", id, field)
351			case string(raw) == "null":
352				return fmt.Errorf("voting proposal %q tally field %q is null", id, field)
353			case !isInt64Number(raw):
354				return fmt.Errorf("voting proposal %q tally field %q has wrong type: want integer, got %s",
355					id, field, jsonValueType(raw))
356			}
357			return nil
358		}
359		if err := check("for_weight", t.forWeightRaw); err != nil {
360			return err
361		}
362		if err := check("against_weight", t.againstWeightRaw); err != nil {
363			return err
364		}
365		return nil
366	}
367	
368	// storedVoteProposal 按成员提交顺序保存成员与委托（顺序不影响相等性），
369	// 动作文本与顺序原样保存（顺序影响相等性）。
370	type storedVoteProposal struct {
371		ID          string             `json:"id"`
372		State       string             `json:"state"`
373		Members     []storedMember     `json:"members"`
374		Delegations []storedDelegation `json:"delegations"`
375		Quorum      int64              `json:"quorum"`
376		StartAt     int64              `json:"start_at"`
377		Deadline    int64              `json:"deadline"`
378		TimelockEnd int64              `json:"timelock_end"`
379		Actions     []string           `json:"actions"`
380		Ballots     []storedBallot     `json:"ballots"`
381		Tally       *storedTally       `json:"tally,omitempty"`
382	}
383	
384	// ---- 校验与派生 ----
385	
386	type proposalSpec struct {
387		members  []VoteMember
388		weights  map[string]int64
389		delegate map[string]string // 直接委托对象
390		pathOf   map[string][]string
391		headOf   map[string]string // 最终代表
392		groupW   map[string]int64  // 最终代表名下归集的全部原始权重
393		total    int64
394	}
395	
396	// validateProposalInput 校验全部创建规则并派生委托路径与代表权重。
397	// 任何非法条件都返回错误，调用方必须整项拒绝。
398	func validateProposalInput(in *CreateVoteInput) (*proposalSpec, error) {
399		if in.ID == "" {
400			return nil, invalidProposal("proposal id must not be empty")
401		}
402		if len(in.Members) == 0 {
403			return nil, invalidProposal("proposal %s: member list must not be empty", in.ID)
404		}
405		weights := make(map[string]int64, len(in.Members))
406		order := make([]string, 0, len(in.Members))
407		for _, m := range in.Members {
408			if m.ID == "" {
409				return nil, invalidProposal("proposal %s: member id must not be empty", in.ID)
410			}
411			if _, dup := weights[m.ID]; dup {
412				return nil, invalidProposal("proposal %s: duplicate member %q", in.ID, m.ID)
413			}
414			if m.Weight <= 0 {
415				return nil, invalidProposal("proposal %s: member %q weight must be a positive integer, got %d", in.ID, m.ID, m.Weight)
416			}
417			weights[m.ID] = m.Weight
418			order = append(order, m.ID)
419		}
420	
421		// 总权重必须在 int64 范围内（各权重已为正）。
422		var total int64
423		for _, m := range in.Members {
424			sum, ok := addInt64(total, m.Weight)
425			if !ok {
426				return nil, invalidProposal("proposal %s: total member weight overflows int64", in.ID)
427			}
428			total = sum
429		}
430	
431		if in.Quorum < 1 || in.Quorum > total {
432			return nil, invalidProposal("proposal %s: quorum must be between 1 and total weight %d, got %d", in.ID, total, in.Quorum)
433		}
434		if !(0 <= in.StartAt && in.StartAt < in.Deadline && in.Deadline <= in.TimelockEnd) {
435			return nil, invalidProposal("proposal %s: times must satisfy 0 <= start < deadline <= timelock, got start=%d deadline=%d timelock=%d",
436				in.ID, in.StartAt, in.Deadline, in.TimelockEnd)
437		}
438	
439		delegate := make(map[string]string, len(in.Delegations))
440		for _, d := range in.Delegations {
441			if d.From == "" || d.To == "" {
442				return nil, invalidProposal("proposal %s: delegation members must not be empty", in.ID)
443			}
444			if _, ok := weights[d.From]; !ok {
445				return nil, invalidProposal("proposal %s: delegation from unknown member %q", in.ID, d.From)
446			}
447			if _, ok := weights[d.To]; !ok {
448				return nil, invalidProposal("proposal %s: delegation to unknown member %q", in.ID, d.To)
449			}
450			if d.From == d.To {
451				return nil, invalidProposal("proposal %s: member %q must not delegate to itself", in.ID, d.From)
452			}
453			if _, dup := delegate[d.From]; dup {
454				return nil, invalidProposal("proposal %s: member %q delegates more than once", in.ID, d.From)
455			}
456			delegate[d.From] = d.To
457		}
458	
459		// 解析每名成员的委托路径：从本人出发，沿直接委托对象逐次前行，
460		// 直到未再委托的最终代表。每个成员出度至多 1，且自委托/循环已被拦截，
461		// 所以该遍历必然终止。
462		// 命中已解析成员时必须拼接其“完整路径”（去掉与之重复的衔接点），
463		// 不能直接跳到它的最终代表，否则多跳链上的中间委托对象会丢失。
464		// 结果只依赖委托关系本身，与成员及委托参数的提交顺序无关。
465		pathOf := make(map[string][]string, len(weights))
466		headOf := make(map[string]string, len(weights))
467		for _, id := range order {
468			if _, done := headOf[id]; done {
469				continue
470			}
471			chain := []string{id}
472			onChain := map[string]int{id: 0}
473			cur := id
474			for {
475				next, has := delegate[cur]
476				if !has {
477					break // cur 即未再委托的最终代表
478				}
479				if pos, cyc := onChain[next]; cyc {
480					return nil, invalidProposal("proposal %s: delegation cycle involving %q", in.ID, chain[pos])
481				}
482				if resolved, ok := pathOf[next]; ok {
483					// 拼接已解析的完整后缀；resolved[0] == next，逐跳衔接且无重复成员。
484					chain = append(chain, resolved...)
485					cur = resolved[len(resolved)-1]
486					break
487				}
488				chain = append(chain, next)
489				onChain[next] = len(chain) - 1
490				cur = next
491			}
492			head := cur
493			// 链上每个成员的路径都是自身到 head 的后缀。命中已解析后缀时，
494			// 后缀成员均已登记，这里只补齐尚未解析的成员。
495			for i := 0; i < len(chain); i++ {
496				member := chain[i]
497				if _, ok := headOf[member]; !ok {
498					pathOf[member] = append([]string(nil), chain[i:]...)
499					headOf[member] = head
500				}
501			}
502		}
503	
504		// 归集每个最终代表名下的全部原始权重；子集和必然不超过总权重。
505		groupW := make(map[string]int64)
506		for _, id := range order {
507			head := headOf[id]
508			sum, ok := addInt64(groupW[head], weights[id])
509			if !ok {
510				return nil, invalidProposal("proposal %s: delegated weight for %q overflows int64", in.ID, head)
511			}
512			groupW[head] = sum
513		}
514	
515		return &proposalSpec{
516			members:  append([]VoteMember(nil), in.Members...),
517			weights:  weights,
518			delegate: delegate,
519			pathOf:   pathOf,
520			headOf:   headOf,
521			groupW:   groupW,
522			total:    total,
523		}, nil
524	}
525	
526	func invalidProposal(format string, args ...any) error {
527		return fmt.Errorf("%w: %s", ErrInvalidProposal, fmt.Sprintf(format, args...))
528	}
529	
530	// proposalsEqual 判断重试内容是否与已存提案逐项相同。
531	// 成员与委托的输入次序不影响比较；动作文本与顺序必须一致。
532	func proposalsEqual(stored *storedVoteProposal, in *CreateVoteInput, spec *proposalSpec) bool {
533		if stored.Quorum != in.Quorum || stored.StartAt != in.StartAt ||
534			stored.Deadline != in.Deadline || stored.TimelockEnd != in.TimelockEnd {
535			return false
536		}
537		if !sameActions(stored.Actions, in.Actions) {
538			return false
539		}
540		if len(stored.Members) != len(in.Members) {
541			return false
542		}
543		for _, m := range stored.Members {
544			if w, ok := spec.weights[m.ID]; !ok || w != m.Weight {
545				return false
546			}
547		}
548		if len(stored.Delegations) != len(in.Delegations) {
549			return false
550		}
551		for _, d := range stored.Delegations {
552			to, ok := spec.delegate[d.From]
553			if !ok || to != d.To {
554				return false
555			}
556		}
557		return true
558	}
559	
560	// ---- 存储操作 ----
561	
562	// CreateVoteProposal 创建一项投票提案。
563	// 同编号且全部内容相同的重试返回已存在提案（existed=true）且不改变任何状态；
564	// 同编号内容不同（或编号已被 register 来源占用）返回 ErrProposalConflict。
565	// 非法条件整项拒绝，不落盘任何部分变化。
566	func (s *Store) CreateVoteProposal(in *CreateVoteInput) (view *VoteProposalView, existed bool, err error) {
567		spec, err := validateProposalInput(in)
568		if err != nil {
569			return nil, false, err
570		}
571		commit, err := s.begin()
572		if err != nil {
573			return nil, false, err
574		}
575		defer commit()
576	
577		state, err := s.loadLocked()
578		if err != nil {
579			return nil, false, err
580		}
581		if existing, ok := state.VoteProposals[in.ID]; ok {
582			if !proposalsEqual(existing, in, spec) {
583				return nil, false, fmt.Errorf("%w: voting proposal %s", ErrProposalConflict, in.ID)
584			}
585			v := voteProposalView(existing)
586			return v, true, nil
587		}
588		if _, ok := state.Proposals[in.ID]; ok {
589			// register 不能覆盖投票提案；反向同样拒绝，两种来源共用编号。
590			return nil, false, fmt.Errorf("%w: proposal id %s already registered", ErrProposalConflict, in.ID)
591		}
592	
593		stored := &storedVoteProposal{
594			ID:          in.ID,
595			State:       "voting",
596			Members:     make([]storedMember, 0, len(in.Members)),
597			Delegations: make([]storedDelegation, 0, len(in.Delegations)),
598			Quorum:      in.Quorum,
599			StartAt:     in.StartAt,
600			Deadline:    in.Deadline,
601			TimelockEnd: in.TimelockEnd,
602			Actions:     copyActions(in.Actions),
603			Ballots:     []storedBallot{},
604		}
605		for _, m := range in.Members {
606			stored.Members = append(stored.Members, storedMember{ID: m.ID, Weight: m.Weight})
607		}
608		for _, d := range in.Delegations {
609			stored.Delegations = append(stored.Delegations, storedDelegation{From: d.From, To: d.To})
610		}
611		state.VoteProposals[in.ID] = stored
612		if err := s.commitLocked(state); err != nil {
613			return nil, false, err
614		}
615		return voteProposalView(stored), false, nil
616	}
617	
618	func voteReject(reason string) error {
619		return fmt.Errorf("%w: %s", ErrVoteRejected, reason)
620	}
621	
622	func tallyReject(reason string) error {
623		return fmt.Errorf("%w: %s", ErrTallyRejected, reason)
624	}
625	
626	// ---- 计票规则（唯一实现，首次计票、打开校验、查询结论共用） ----
627	
628	// ballotCounts 是按逐票明细汇总出的两侧权重。参与量只统计最终代表
629	// 实际投出的票，未投成员的权重既不在 For 也不在 Against 中，
630	// 因而不会被计入 Turnout，更不能直接拿成员总权重充当参与量。
631	type ballotCounts struct {
632		forWeight     int64
633		againstWeight int64
634	}
635	
636	// turnout 返回参与权重（赞成与反对之和），ok 表示合计未溢出 int64。
637	// 两侧各自不超过合法成员总权重时合计必不溢出；此处仍显式检查，
638	// 使“总权重恰好为 math.MaxInt64”的合法提案也不依赖该前提。
639	func (c ballotCounts) turnout() (int64, bool) {
640		return addInt64(c.forWeight, c.againstWeight)
641	}
642	
643	// votePasses 是唯一的通过条件：参与权重达到法定人数（恰好达到也算）
644	// 且赞成严格多于反对。平票、无人投票或参与不足一律不通过。
645	// 通过比较法定人数剩余容量判断参与量，避免 for+against 上溢时回绕为负，
646	// 把已达标（乃至总权重恰好为 int64 上限）的提案误判为参与不足。
647	func votePasses(forWeight, againstWeight, quorum int64) bool {
648		if forWeight <= againstWeight {
649			return false // 平票或赞成更少都不通过；两侧非负，无票时同样落在这里
650		}
651		return forWeight >= quorum-againstWeight // 等价于 for+against >= quorum，且不做上溢加法
652	}
653	
654	// tallyVerdict 把通过条件映射为提案首次计票后的状态。
655	func tallyVerdict(passed bool) string {
656		if passed {
657			return "passed"
658		}
659		return "rejected"
660	}
661	
662	// countBallots 只按票据选择累加两侧权重，不做代表资格与票重核对
663	// （资格核对由 verifyBallots 负责）。任何一侧溢出 int64 都返回损坏错误。
664	func countBallots(ballots []storedBallot) (ballotCounts, error) {
665		var c ballotCounts
666		for _, b := range ballots {
667			if b.Support {
668				sum, ok := addInt64(c.forWeight, b.Weight)
669				if !ok {
670					return ballotCounts{}, errors.New("for-side ballot weights overflow int64")
671				}
672				c.forWeight = sum
673			} else {
674				sum, ok := addInt64(c.againstWeight, b.Weight)
675				if !ok {
676					return ballotCounts{}, errors.New("against-side ballot weights overflow int64")
677				}
678				c.againstWeight = sum
679			}
680		}
681		return c, nil
682	}
683	
684	// verifyBallots 依据成员名单与委托关系逐票核对并汇总：
685	// 代表必须是最终代表、不得重复、票重必须等于委托后归集到其名下的权重。
686	// 这些条件全部由打开状态文件时的严格校验保证，首次计票路径再核对一次，
687	// 使两条路径对“票重/代表是否可信”的判定使用同一份规则。
688	// 汇总只含实际投出的票；任一条件不符返回带具体原因的错误，
689	// 错误分类（ErrStateCorrupt）由调用方按自身路径统一包装。
690	func verifyBallots(id string, ballots []storedBallot, spec *proposalSpec) (ballotCounts, error) {
691		seen := map[string]bool{}
692		for i, b := range ballots {
693			if b.Representative == "" {
694				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d has empty representative", id, i)
695			}
696			if spec.headOf[b.Representative] != b.Representative {
697				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d: %q is not a final representative",
698					id, i, b.Representative)
699			}
700			if seen[b.Representative] {
701				return ballotCounts{}, fmt.Errorf("proposal %s has duplicate stored ballot for %q", id, b.Representative)
702			}
703			seen[b.Representative] = true
704			if b.Weight != spec.groupW[b.Representative] {
705				return ballotCounts{}, fmt.Errorf("proposal %s ballot weight for %q (%d) does not match roster delegation (%d)",
706					id, b.Representative, b.Weight, spec.groupW[b.Representative])
707			}
708		}
709		counts, err := countBallots(ballots)
710		if err != nil {
711			return ballotCounts{}, fmt.Errorf("proposal %s %v", id, err)
712		}
713		return counts, nil
714	}
715	
716	// CastVote 在一项投票提案上投票。调用方通过 now 提供当前时间。
717	// 只有最终代表本人可投赞成/反对票，每位代表一张票，票重为归集到其名下的
718	// 全部原始权重。相同选择的重试始终返回首次记录；改投报冲突。
719	// 首次投票只接受 start <= now < deadline；计票之后拒绝一切新票。
720	func (s *Store) CastVote(id, voter string, support bool, now int64) (*BallotView, error) {
721		if voter == "" {
722			return nil, voteReject("voter id must not be empty")
723		}
724		commit, err := s.begin()
725		if err != nil {
726			return nil, err
727		}
728		defer commit()
729	
730		state, err := s.loadLocked()
731		if err != nil {
732			return nil, err
733		}
734		p, ok := state.VoteProposals[id]
735		if !ok {
736			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
737		}
738		spec, verr := specOf(p)
739		if verr != nil {
740			return nil, verr // 正常路径不会发生：打开与提交前均已严格校验
741		}
742		if _, member := spec.weights[voter]; !member {
743			return nil, voteReject(fmt.Sprintf("voter %q is not on the member roster of %s", voter, id))
744		}
745		if spec.headOf[voter] != voter {
746			return nil, voteReject(fmt.Sprintf("voter %q has delegated the vote to %q and may not vote directly", voter, spec.headOf[voter]))
747		}
748		// 已投过票：相同选择的重试始终返回首次记录（与时间窗口、是否已计票无关）；
749		// 改投另一选择报冲突，绝不静默覆盖。
750		for i := range p.Ballots {
751			if p.Ballots[i].Representative == voter {
752				if p.Ballots[i].Support != support {
753					return nil, fmt.Errorf("%w: representative %q already voted %s for %s; changing the vote is not allowed",
754						ErrProposalConflict, voter, voteChoice(p.Ballots[i].Support), id)
755				}
756				b := p.Ballots[i]
757				return &BallotView{Representative: b.Representative, Weight: b.Weight, Support: b.Support, VotedAt: b.VotedAt}, nil
758			}
759		}
760		if p.Tally != nil {
761			return nil, voteReject(fmt.Sprintf("proposal %s has already been tallied; voting is closed", id))
762		}
763		if now < p.StartAt || now >= p.Deadline {
764			return nil, voteReject(fmt.Sprintf("proposal %s is not open for voting at now=%d (start=%d deadline=%d)", id, now, p.StartAt, p.Deadline))
765		}
766	
767		p.Ballots = append(p.Ballots, mustStoreBallot(voter, spec.groupW[voter], support, now))
768		if err := s.commitLocked(state); err != nil {
769			return nil, err
770		}
771		return &BallotView{Representative: voter, Weight: spec.groupW[voter], Support: support, VotedAt: now}, nil
772	}
773	
774	func voteChoice(support bool) string {
775		if support {
776			return "for"
777		}
778		return "against"
779	}
780	
781	// TallyVote 在截止时刻或之后进行首次计票：赞成与反对权重之和达到法定人数，
782	// 且赞成严格多于反对才通过。未投权重不计入参与量。
783	// 计票只确定状态，不转账；再次计票始终返回首次结论。
784	func (s *Store) TallyVote(id string, now int64) (*TallyResultView, error) {
785		commit, err := s.begin()
786		if err != nil {
787			return nil, err
788		}
789		defer commit()
790	
791		state, err := s.loadLocked()
792		if err != nil {
793			return nil, err
794		}
795		p, ok := state.VoteProposals[id]
796		if !ok {
797			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
798		}
799		if p.Tally != nil {
800			return storedTallyResult(p), nil
801		}
802		if now < p.Deadline {
803			return nil, tallyReject(fmt.Sprintf("voting for %s is still open: now=%d deadline=%d", id, now, p.Deadline))
804		}
805	
806		spec, verr := specOf(p)
807		if verr != nil {
808			return nil, verr
809		}
810		// 计票规则只有一份：同一套“代表资格 + 票重 + 两侧汇总 + 法定人数/多数”
811		// 同时用于首次计票、打开文件时的重放校验与查询结论。
812		counts, verr := verifyBallots(id, p.Ballots, spec)
813		if verr != nil {
814			return nil, fmt.Errorf("%w: %v", ErrStateCorrupt, verr)
815		}
816		passed := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
817		p.Tally = mustStoreTally(counts.forWeight, counts.againstWeight, now)
818		p.State = tallyVerdict(passed)
819		if err := s.commitLocked(state); err != nil {
820			return nil, err
821		}
822		return storedTallyResult(p), nil
823	}
824	
825	// storedTallyResult 从已存储提案重建首次计票结论；尚未计票时返回 nil。
826	// Passed 由唯一的通过规则（votePasses）按保存权重重算：提案后续执行
827	// （executed）不改变首次结论，查询结论与首次计票结论因此始终一致。
828	// 调用方持有的状态均经过 validateState，两侧合计必然不超过合法总权重。
829	func storedTallyResult(p *storedVoteProposal) *TallyResultView {
830		if p.Tally == nil {
831			return nil
832		}
833		c := ballotCounts{forWeight: p.Tally.ForWeight, againstWeight: p.Tally.AgainstWeight}
834		turnout, _ := c.turnout()
835		return &TallyResultView{
836			ForWeight:     c.forWeight,
837			AgainstWeight: c.againstWeight,
838			Turnout:       turnout,
839			Quorum:        p.Quorum,
840			Passed:        votePasses(c.forWeight, c.againstWeight, p.Quorum),
841			TalliedAt:     p.Tally.TalliedAt,
842		}
843	}
844	
845	// VoteProposal 按编号查询一项投票提案；不存在时 ok 为 false。
846	func (s *Store) VoteProposal(id string) (*VoteProposalView, bool, error) {
847		state, err := s.readState()
848		if err != nil {
849			return nil, false, err
850		}
851		p, ok := state.VoteProposals[id]
852		if !ok {
853			return nil, false, nil
854		}
855		return voteProposalView(p), true, nil
856	}
857	
858	// VoteProposals 返回全部投票提案，按编号排序。
859	func (s *Store) VoteProposals() ([]*VoteProposalView, error) {
860		state, err := s.readState()
861		if err != nil {
862			return nil, err
863		}
864		return voteProposalViews(state), nil
865	}
866	
867	func voteProposalViews(state *storedState) []*VoteProposalView {
868		out := make([]*VoteProposalView, 0, len(state.VoteProposals))
869		for _, p := range state.VoteProposals {
870			out = append(out, voteProposalView(p))
871		}
872		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
873		return out
874	}
875	
876	func voteProposalView(p *storedVoteProposal) *VoteProposalView {
877		spec, err := specOf(p)
878		if err != nil {
879			// 调用方持有的状态均经过 validateState；损坏文件根本无法打开。
880			panic("govflow: building view of corrupt proposal: " + err.Error())
881		}
882		members := make([]MemberView, 0, len(p.Members))
883		for _, m := range p.Members { // 保持成员提交顺序
884			mv := MemberView{
885				ID:       m.ID,
886				Weight:   m.Weight,
887				Path:     append([]string(nil), spec.pathOf[m.ID]...),
888				Delegate: spec.headOf[m.ID],
889			}
890			if to, ok := spec.delegate[m.ID]; ok {
891				mv.Direct = to
892			}
893			members = append(members, mv)
894		}
895		ballots := make([]BallotView, 0, len(p.Ballots))
896		for _, b := range p.Ballots { // 保持首次投票先后顺序
897			ballots = append(ballots, BallotView{
898				Representative: b.Representative,
899				Weight:         b.Weight,
900				Support:        b.Support,
901				VotedAt:        b.VotedAt,
902			})
903		}
904		v := &VoteProposalView{
905			ID:          p.ID,
906			Source:      "vote",
907			State:       p.State,
908			Quorum:      p.Quorum,
909			StartAt:     p.StartAt,
910			Deadline:    p.Deadline,
911			TimelockEnd: p.TimelockEnd,
912			Actions:     copyActions(p.Actions),
913			TotalWeight: spec.total,
914			Members:     members,
915			Ballots:     ballots,
916		}
917		if p.Tally != nil {
918			v.Tally = storedTallyResult(p)
919		}
920		return v
921	}
922	
923	// specOf 从已存储提案重建校验派生物（委托路径、代表归集权重）。
924	func specOf(p *storedVoteProposal) (*proposalSpec, error) {
925		in := &CreateVoteInput{
926			ID:          p.ID,
927			Quorum:      p.Quorum,
928			StartAt:     p.StartAt,
929			Deadline:    p.Deadline,
930			TimelockEnd: p.TimelockEnd,
931			Actions:     p.Actions,
932		}
933		in.Members = make([]VoteMember, len(p.Members))
934		for i, m := range p.Members {
935			in.Members[i] = VoteMember{ID: m.ID, Weight: m.Weight}
936		}
937		in.Delegations = make([]Delegation, len(p.Delegations))
938		for i, d := range p.Delegations {
939			in.Delegations[i] = Delegation{From: d.From, To: d.To}
940		}
941		return validateProposalInput(in)
942	}
943	
944	// validateVoteProposals 在打开状态文件时严格校验全部投票提案：
945	// 编号与 register 来源不冲突；状态机与计票结论一致；票重/代表与名单及委托明细一致；
946	// 首次投票时间落在窗口内；首次计票不早于截止且结论可由明细重放。
947	func validateVoteProposals(state *storedState) error {
948		for key, p := range state.VoteProposals {
949			if p == nil {
950				return fmt.Errorf("voting proposal %q is empty", key)
951			}
952			if p.ID != key || p.ID == "" {
953				return fmt.Errorf("voting proposal key %q does not match id %q", key, p.ID)
954			}
955			if _, collide := state.Proposals[p.ID]; collide {
956				return fmt.Errorf("proposal id %q exists in both proposal sources", p.ID)
957			}
958			switch p.State {
959			case "voting", "passed", "rejected", "executed":
960			default:
961				return fmt.Errorf("voting proposal %q has unknown state %q", p.ID, p.State)
962			}
963			spec, err := specOf(p)
964			if err != nil {
965				return err
966			}
967	
968			// 每张已保存票据都必须明确写出 representative/weight/support/voted_at
969			// 且非 null、JSON 类型正确。先于代表资格与票重核对执行：字段缺损时直接判
970			// 整份文件损坏，绝不能把缺失的 support 默认成反对票、把缺失的 voted_at
971			// 默认成 0 后再继续给出查询或计票的部分结果。
972			for i := range p.Ballots {
973				if err := validateStoredBallot(p.ID, i, &p.Ballots[i]); err != nil {
974					return err
975				}
976			}
977	
978			// 票据明细的代表资格、重复票据、票重与两侧汇总，全部复用首次计票的
979			// verifyBallots：打开重放与首次计票对“票重/代表是否可信”只有一份判定，
980			// 汇总只含最终代表实际投出的票，未投成员权重不进入参与量。
981			counts, err := verifyBallots(p.ID, p.Ballots, spec)
982			if err != nil {
983				return err
984			}
985			// 首次投票时间必须落在窗口 [start, deadline) 内；此约束与票重汇总无关，
986			// 仍只属于打开时的明细校验。
987			for _, b := range p.Ballots {
988				if b.VotedAt < p.StartAt || b.VotedAt >= p.Deadline {
989					return fmt.Errorf("voting proposal %q ballot by %q cast at %d outside window [%d,%d)",
990						p.ID, b.Representative, b.VotedAt, p.StartAt, p.Deadline)
991				}
992			}
993	
994			switch {
995			case p.Tally == nil:
996				if p.State != "voting" {
997					return fmt.Errorf("voting proposal %q is %s but has no tally", p.ID, p.State)
998				}
999			default:
1000				if p.State == "voting" {
1001					return fmt.Errorf("voting proposal %q has a tally but is still in voting state", p.ID)
1002				}
1003				// 只要提案有计票结果，for_weight 与 against_weight 就必须各自明确
1004				// 写出且为 int64 整数。先于权重重放核对执行：字段缺损时直接判整份
1005				// 文件损坏，绝不能把缺失的一侧默认补成 0（恰好等于该侧真实零票重）
1006				// 后再继续给出查询或再次计票的结果。明确写出的 0 是合法权重。
1007				if err := validateStoredTally(p.ID, p.Tally); err != nil {
1008					return err
1009				}
1010				if p.Tally.TalliedAt < p.Deadline {
1011					return fmt.Errorf("voting proposal %q tallied at %d before deadline %d", p.ID, p.Tally.TalliedAt, p.Deadline)
1012				}
1013				if p.Tally.ForWeight != counts.forWeight || p.Tally.AgainstWeight != counts.againstWeight {
1014					return fmt.Errorf("voting proposal %q tally weights for=%d/against=%d do not replay ballots for=%d/against=%d",
1015						p.ID, p.Tally.ForWeight, p.Tally.AgainstWeight, counts.forWeight, counts.againstWeight)
1016				}
1017				// 通过条件同样只有一份：保存状态必须与票据重放出的结论一致，
1018				// executed 是 passed 提案执行后的后继状态，仍对应“首次通过”。
1019				passedNow := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
1020				if passedNow != (p.State == "passed" || p.State == "executed") {
1021					return fmt.Errorf("voting proposal %q state %s does not match quorum/majority replay", p.ID, p.State)
1022				}
1023			}
1024		}
1025		return nil
1026	}
1027

